-- Auto-generated Nigerian Secondary School Dataset (Randomized Interleaved Class Streams)
-- Session: 2024/2025, Term: First Term

CREATE TABLE IF NOT EXISTS students (
    id SERIAL PRIMARY KEY,
    matric_number VARCHAR(20) UNIQUE NOT NULL,
    student_name VARCHAR(100) NOT NULL,
    class VARCHAR(30) NOT NULL,
    stream VARCHAR(30) NOT NULL
);

CREATE TABLE IF NOT EXISTS subjects (
    subject_id SERIAL PRIMARY KEY,
    subject_code VARCHAR(20) UNIQUE NOT NULL,
    subject_name VARCHAR(100) NOT NULL,
    category VARCHAR(30) NOT NULL
);

CREATE TABLE IF NOT EXISTS results (
    id SERIAL PRIMARY KEY,
    matric_number VARCHAR(20) REFERENCES students(matric_number) ON DELETE CASCADE,
    access_pin VARCHAR(100) NOT NULL,
    term VARCHAR(20) NOT NULL,
    session VARCHAR(20) NOT NULL,
    grade VARCHAR(5) NOT NULL,
    teacher_remark TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (matric_number, term, session)
);

CREATE TABLE IF NOT EXISTS student_scores (
    id SERIAL PRIMARY KEY,
    matric_number VARCHAR(20) REFERENCES students(matric_number) ON DELETE CASCADE,
    subject_id INTEGER REFERENCES subjects(subject_id) ON DELETE CASCADE,
    score INTEGER CHECK (score BETWEEN 0 AND 100),
    term VARCHAR(20) NOT NULL,
    session VARCHAR(20) NOT NULL,
    UNIQUE (matric_number, subject_id, term, session)
);

